{
  "constraints": [
    {
      "constraint": "若画面完整呈现神舟七号飞船，则飞船本体由轨道舱、返回舱、推进舱三个舱段串联组成。",
      "polarity": "must_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "若画面呈现轨道舱，则轨道舱带有气闸舱或出舱舱门结构。",
      "polarity": "must_have",
      "variants": [],
      "source": "desc"
    },
    {
      "constraint": "若画面呈现返回舱，则返回舱呈钟形/钝头舱体，而非圆柱形卫星舱或带翼舱体。",
      "polarity": "must_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "若飞船外部表面清晰可见，则外观至少呈现一种中国/神舟标识。",
      "polarity": "must_have",
      "variants": [
        "中国国旗",
        "中国载人航天工程标志",
        "神舟字样"
      ],
      "source": "common_sense"
    },
    {
      "constraint": "若画面呈现发射场景，则运载火箭为带逃逸塔的长征二号F构型。",
      "polarity": "must_have",
      "variants": [],
      "source": "desc"
    },
    {
      "constraint": "不得将神舟七号飞船整体呈现为带固定机翼的航天飞机、带大型桁架/多舱组合的空间站或无返回舱的无人卫星平台。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    }
  ]
}
